corporate_design.toad_component_blueprint:
canvas {
  size: 960px 580px;
  fill: #050811;
  font-family: "Fira Code, monospace";
}

>vaultBlack = #050811;
>terminalCyan = #00F0FF;
>breachRed = #FF0055;
>shieldBorder = #1A263D;
>textLight = #F0F6FC;

rect #outerShield {
  at: center of canvas;
  size: 880px 500px;
  fill: #080D1A;
  stroke: >shieldBorder;
  stroke-width: 2px;
  radius: 4px;
}

text #vaultHeader {
  at: top left of #outerShield offset 32px 28px;
  content: "CYBERVAULT // ZERO-TRUST SHIELD v4.2";
  font-size: 16px;
  font-weight: 700;
  color: >terminalCyan;
}

rect #alertCard {
  at: below #vaultHeader offset 24px;
  size: 816px 80px;
  fill: #140810;
  stroke: >breachRed;
  stroke-width: 1px;
  radius: 2px;
}

text #alertTitle {
  at: left center of #alertCard offset 24px 0px;
  content: "⚠ ATTACK BLOCKED: DDOS LAYER-7 FLOOD (14.2 Tbps)";
  font-size: 14px;
  font-weight: 700;
  color: >breachRed;
}

rect #statusGrid {
  at: below #alertCard offset 24px;
  size: 816px 240px;
  fill: #0A1224;
  stroke: >shieldBorder;
  stroke-width: 1px;
  radius: 2px;
}

text #statusTelemetry {
  at: top left of #statusGrid offset 24px 24px;
  size: 760px;
  content: "CRYPTOGRAPHIC INTEGRITY: SHA-512 VERIFIED\nENCRYPTION: POST-QUANTUM KYBER-1024\nACTIVE ENCLAVES: 128 ISOLATED NODES";
  font-size: 13px;
  color: >textLight;
}
